'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var smallPositive = require( './fixtures/python/small_positive.json' );
var smallNegative = require( './fixtures/python/small_negative.json' );
var mediumPositive = require( './fixtures/python/medium_positive.json' );
var mediumNegative = require( './fixtures/python/medium_negative.json' );
var largePositive = require( './fixtures/python/large_positive.json' );
var largeNegative = require( './fixtures/python/large_negative.json' );
var veryLarge = require( './fixtures/python/very_large.json' );


// VARIABLES //

var sici = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( sici instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sici, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the sine and cosine integrals (small positive values)', opts, function test( t ) {
	var expectedSi;
	var expectedCi;
	var delta;
	var tol;
	var x;
	var v;
	var i;

	x = smallPositive.x;
	expectedSi = smallPositive.si;
	expectedCi = smallPositive.ci;

	for ( i = 0; i < x.length; i++ ) {
		v = sici( x[ i ] );
		t.strictEqual( isFloat64Array( v ), true, 'returns a Float64Array' );

		// Check Si(x):
		if ( v[ 0 ] === expectedSi[ i ] ) {
			t.strictEqual( v[ 0 ], expectedSi[ i ], 'x: '+x[i]+'. Si(x) Expected: '+expectedSi[i] );
		} else {
			delta = abs( v[ 0 ] - expectedSi[ i ] );
			tol = max( 10.0 * EPS, 10.0 * EPS * abs( expectedSi[ i ] ) );
			t.ok( delta <= tol, 'within tolerance. x: '+x[i]+'. Si(x): '+v[0]+'. E: '+expectedSi[i]+'. tol: '+tol+'. Δ: '+delta+'.' );
		}

		// Check Ci(x):
		if ( v[ 1 ] === expectedCi[ i ] ) {
			t.strictEqual( v[ 1 ], expectedCi[ i ], 'x: '+x[i]+'. Ci(x) Expected: '+expectedCi[i] );
		} else {
			delta = abs( v[ 1 ] - expectedCi[ i ] );
			tol = max( 10.0 * EPS, 10.0 * EPS * abs( expectedCi[ i ] ) );
			t.ok( delta <= tol, 'within tolerance. x: '+x[i]+'. Ci(x): '+v[1]+'. E: '+expectedCi[i]+'. tol: '+tol+'. Δ: '+delta+'.' );
		}
	}
	t.end();
});

