tape( 'the function returns `[NaN, NaN]` if provided `NaN`', opts, function test( t ) {
	var v = sici( NaN );
	t.strictEqual( isnan( v[ 0 ] ), true, 'Si returns NaN' );
	t.strictEqual( isnan( v[ 1 ] ), true, 'Ci returns NaN' );
	t.end();
});

tape( 'the function returns `[0.0, -Infinity]` if provided `0.0`', opts, function test( t ) {
	var v = sici( 0.0 );
	t.strictEqual( v[ 0 ], 0.0, 'Si(0) returns 0.0' );
	t.strictEqual( v[ 1 ], NINF, 'Ci(0) returns -Infinity' );
	t.end();
});
